import { useMemo, useState } from "react";
import { trpc } from "@/lib/trpc";
import { toast } from "sonner";
import LegacyInventoryWindows from "@/components/LegacyInventoryWindows";
import {
  Activity, ArrowDownToLine, ArrowUpFromLine, BarChart3, Boxes, Check,
  ChevronLeft, CircleDollarSign, ClipboardList, FileBarChart, FilePlus2,
  Gauge, Landmark, LayoutDashboard, Menu, Package, PanelRight, Plus,
  RefreshCw, Search, Settings2, ShieldCheck, ShoppingCart, Users, WalletCards,
  X,
} from "lucide-react";

type TabId = "dashboard" | "accounts" | "journals" | "sales" | "purchases" | "inventory" | "receipts" | "payments" | "cashbanks" | "reports" | "setup" | "permissions";

type JournalLine = { accountCode: string; description: string; debit: string; credit: string };

const tabs: Array<{ id: TabId; label: string; hint: string; icon: typeof LayoutDashboard }> = [
  { id: "dashboard", label: "الرئيسية", hint: "مؤشرات النظام", icon: LayoutDashboard },
  { id: "accounts", label: "دليل الحسابات", hint: "الحسابات والربط", icon: Landmark },
  { id: "journals", label: "القيود اليومية", hint: "إنشاء وترحيل", icon: FilePlus2 },
  { id: "sales", label: "المبيعات والذمم", hint: "الفواتير والتحصيل", icon: ArrowUpFromLine },
  { id: "purchases", label: "المشتريات والدائنون", hint: "أوامر واستلام", icon: ArrowDownToLine },
  { id: "inventory", label: "المخزون", hint: "المستودعات والجرد والحركة", icon: Package },
  { id: "receipts", label: "سندات القبض", hint: "تحصيل وتخصيص", icon: ArrowDownToLine },
  { id: "payments", label: "سندات الصرف", hint: "دفع وتسوية", icon: ArrowUpFromLine },
  { id: "cashbanks", label: "الصناديق والبنوك", hint: "الحسابات النقدية", icon: WalletCards },
  { id: "reports", label: "التقارير", hint: "GL وميزان المراجعة", icon: FileBarChart },
  { id: "setup", label: "بيانات النظام", hint: "الشركة والفترات", icon: Settings2 },
  { id: "permissions", label: "الصلاحيات", hint: "الأدوار والاعتماد", icon: ShieldCheck },
];

const money = (value: unknown) => Number(value || 0).toLocaleString("ar-YE", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const number = (value: unknown) => Number(value || 0).toLocaleString("ar-YE");

function Status({ children, tone = "neutral" }: { children: React.ReactNode; tone?: "success" | "warning" | "danger" | "neutral" }) {
  return <span className={`suite-status ${tone}`}><i />{children}</span>;
}

function Metric({ label, value, detail, icon: Icon, tone }: { label: string; value: string | number; detail: string; icon: typeof Gauge; tone: string }) {
  return <article className="suite-metric"><div className={`suite-metric-icon ${tone}`}><Icon size={19} /></div><div><span>{label}</span><strong>{value}</strong><small>{detail}</small></div></article>;
}

function SectionHeader({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: React.ReactNode }) {
  return <div className="suite-section-head"><div><p className="suite-eyebrow">{eyebrow}</p><h2>{title}</h2><p>{description}</p></div>{action}</div>;
}

function EmptyState({ title, detail, icon: Icon = ClipboardList }: { title: string; detail: string; icon?: typeof ClipboardList }) {
  return <div className="suite-empty"><Icon size={26} /><b>{title}</b><span>{detail}</span></div>;
}

function Dashboard({ onNavigate }: { onNavigate: (tab: TabId) => void }) {
  const dashboard = trpc.dashboard.useQuery();
  const master = trpc.masterData.useQuery();
  const reconciliation = trpc.windows.reconciliation.useQuery({ companyId: 1 });
  const periods = trpc.erpWorkspace.fiscalPeriods.useQuery({ companyId: 1 });
  const stats = dashboard.data ?? { invoices: 0, journals: 0, stockValue: "0", windows: 0, domains: 0 };
  const masterData = master.data ?? { customers: [], suppliers: [], items: [], warehouses: [], accounts: [] };
  const openPeriods = (periods.data ?? []).filter((period: any) => ["OPEN", "REOPENED"].includes(String(period.status))).length;
  return <>
    <section className="suite-hero"><div><div className="suite-hero-label"><Activity size={14} /> منصة ONEX المحاسبية · إصدار اليمن</div><h2>نظام مالي واضح،<br /><em>مبني على النواة.</em></h2><p>وحدة محاسبية جديدة مستقلة عن النوافذ القديمة، تجمع دفتر الأستاذ والذمم والمخزون والمشتريات والمبيعات في دورة تشغيل واحدة قابلة للتدقيق.</p><div className="suite-actions"><button className="suite-primary" onClick={() => onNavigate("journals")}><Plus size={16} />قيد يومية جديد</button><button className="suite-secondary" onClick={() => onNavigate("reports")}><FileBarChart size={16} />فتح التقارير</button></div></div><div className="suite-hero-visual"><div className="suite-orbit orbit-a" /><div className="suite-orbit orbit-b" /><div className="suite-hero-core"><span>ONEX</span><small>FINANCE</small></div><div className="suite-float float-a">GL</div><div className="suite-float float-b">AR</div><div className="suite-float float-c">INV</div></div></section>
    <section className="suite-metrics"><Metric label="الفواتير المرحّلة" value={number(stats.invoices)} detail="مبيعات ومشتريات" icon={FilePlus2} tone="cyan" /><Metric label="قيود الأستاذ" value={number(stats.journals)} detail="متوازنة وقابلة للتتبع" icon={Landmark} tone="violet" /><Metric label="قيمة المخزون" value={money(stats.stockValue)} detail="بالريال اليمني" icon={Package} tone="amber" /><Metric label="الفترات المفتوحة" value={number(openPeriods)} detail="جاهزة للترحيل" icon={Gauge} tone="green" /></section>
    <section className="suite-grid-two"><article className="suite-card"><div className="suite-card-head"><div><p className="suite-eyebrow">CONTROL CENTER</p><h3>صحة الدورة المحاسبية</h3></div><Status tone={reconciliation.data?.status === "BALANCED" ? "success" : "warning"}>{reconciliation.data?.status === "BALANCED" ? "متوازن" : "يحتاج مراجعة"}</Status></div><div className="suite-check-list"><div><Check size={15} /><span>ربط القيد بالفاتورة والمستند المصدر</span><b>مفعّل</b></div><div><Check size={15} /><span>منع الترحيل خارج الفترة المفتوحة</span><b>مفعّل</b></div><div><Check size={15} /><span>منع التكرار بمفتاح idempotency</span><b>مفعّل</b></div><div><Check size={15} /><span>سجل التدقيق لكل عملية مالية</span><b>مفعّل</b></div></div></article><article className="suite-card"><div className="suite-card-head"><div><p className="suite-eyebrow">MASTER DATA</p><h3>بيانات التشغيل</h3></div><button className="suite-icon-button" onClick={() => master.refetch()}><RefreshCw size={15} /></button></div><div className="suite-data-grid"><button onClick={() => onNavigate("accounts")}><Landmark size={17} /><b>{number(masterData.accounts?.length)}</b><span>حسابًا</span></button><button onClick={() => onNavigate("sales")}><Users size={17} /><b>{number(masterData.customers?.length)}</b><span>عميلًا</span></button><button onClick={() => onNavigate("purchases")}><ShoppingCart size={17} /><b>{number(masterData.suppliers?.length)}</b><span>موردًا</span></button><button onClick={() => onNavigate("inventory")}><Boxes size={17} /><b>{number(masterData.items?.length)}</b><span>صنفًا</span></button></div></article></section>
    <section className="suite-card suite-module-strip"><div><p className="suite-eyebrow">ACCOUNTING CYCLES</p><h3>افتح الدورة التي تريد تشغيلها</h3></div><div className="suite-cycle-actions"><button onClick={() => onNavigate("sales")}><ArrowUpFromLine size={16} /><span>المبيعات</span><small>فاتورة · مرتجع · تحصيل</small></button><button onClick={() => onNavigate("purchases")}><ArrowDownToLine size={16} /><span>المشتريات</span><small>طلب · استلام · فاتورة</small></button><button onClick={() => onNavigate("inventory")}><Package size={16} /><span>المخزون</span><small>حركة · تحويل · جرد</small></button><button onClick={() => onNavigate("permissions")}><ShieldCheck size={16} /><span>الرقابة</span><small>صلاحيات · اعتماد · إقفال</small></button></div></section>
  </>;
}

function AccountsView() {
  const [search, setSearch] = useState("");
  const accountsQuery = trpc.windows.accountCatalog.useQuery({ search: search || undefined, limit: 500 });
  const accounts = (accountsQuery.data ?? []) as any[];
  const groups = useMemo(() => accounts.reduce((acc: Record<string, any[]>, account: any) => { const key = account.accountType || "OTHER"; acc[key] = [...(acc[key] || []), account]; return acc; }, {}), [accounts]);
  return <><SectionHeader eyebrow="MASTER DATA / GL" title="دليل الحسابات" description="شجرة الحسابات، الحسابات الرقابية، وربط المبيعات والمشتريات والمخزون بالحسابات الصحيحة." action={<button className="suite-primary"><Plus size={15} />حساب جديد</button>} /><div className="suite-toolbar"><div className="suite-search"><Search size={16} /><input placeholder="ابحث بالكود أو اسم الحساب..." value={search} onChange={(event) => setSearch(event.target.value)} /></div><Status tone="success">{accountsQuery.isFetching ? "جارٍ التحميل" : `${number(accounts.length)} حساب`}</Status></div><div className="account-layout"><article className="suite-card account-tree-card"><div className="suite-table-head"><span>الحساب</span><span>النوع</span><span>الطبيعة</span><span>الترحيل</span><span>الحالة</span></div>{Object.entries(groups).map(([type, rows]) => <div key={type} className="account-group"><div className="account-group-title"><span>{type}</span><b>{number(rows.length)}</b></div>{rows.slice(0, 60).map((account: any) => <div className="suite-table-row" key={account.code}><div><b>{account.code}</b><span>{account.name}</span></div><span>{type}</span><span>{account.normalBalance === "CREDIT" ? "دائن" : "مدين"}</span><span>{account.allowPosting === 0 ? "تجميعي" : "حركة"}</span><Status tone={account.status === "ACTIVE" ? "success" : "warning"}>{account.status || "نشط"}</Status></div>)}</div>)}{!accounts.length && <EmptyState title="لا توجد حسابات" detail="أضف الدليل أو طبّق الترحيل الأساسي لقاعدة البيانات." icon={Landmark} />}</article><aside className="suite-card account-principles"><p className="suite-eyebrow">ACCOUNTING RULES</p><h3>قواعد الدليل</h3><div><Check size={15} /><span>الحساب التجميعي لا يقبل الترحيل</span></div><div><Check size={15} /><span>لا يُحذف الحساب المستخدم في قيود</span></div><div><Check size={15} /><span>لكل عميل ومورد حساب فرعي</span></div><div><Check size={15} /><span>حسابات الضرائب والصندوق محددة</span></div></aside></div></>;
}

function JournalView() {
  const [journalNo, setJournalNo] = useState(`JV-${new Date().getFullYear()}-0001`);
  const [description, setDescription] = useState("");
  const [lines, setLines] = useState<JournalLine[]>([{ accountCode: "1100", description: "", debit: "", credit: "" }, { accountCode: "4100", description: "", debit: "", credit: "" }]);
  const accounts = trpc.windows.accountCatalog.useQuery({ limit: 500 });
  const create = trpc.windows.createJournalDraft.useMutation();
  const validate = trpc.windows.validateJournal.useMutation();
  const debits = lines.reduce((sum, line) => sum + Number(line.debit || 0), 0);
  const credits = lines.reduce((sum, line) => sum + Number(line.credit || 0), 0);
  const balanced = Math.abs(debits - credits) < 0.000001 && debits > 0;
  const updateLine = (index: number, key: keyof JournalLine, value: string) => setLines((current) => current.map((line, row) => row === index ? { ...line, [key]: value } : line));
  const addLine = () => setLines((current) => [...current, { accountCode: "", description: "", debit: "", credit: "" }]);
  const saveDraft = async () => { if (!balanced) return toast.error("يجب أن يتساوى المدين والدائن قبل حفظ القيد"); try { const result = await create.mutateAsync({ journalNo, entryType: "MANUAL", actor: "accounting.user", context: { companyId: 1, branchId: 1, warehouseId: 1, fiscalPeriodId: 1, currencyCode: "YER", languageCode: "ar" }, journalDate: new Date().toISOString(), description, lines: lines.map((line) => ({ accountCode: line.accountCode, description: line.description || description, debit: line.debit || "0", credit: line.credit || "0", currencyCode: "YER", exchangeRate: "1" })) }); toast.success(`تم إنشاء مسودة القيد رقم ${result.journalNo || journalNo}`); if (result.id) await validate.mutateAsync({ id: Number(result.id), actor: "accounting.user" }); } catch (error) { toast.error(error instanceof Error ? error.message : "تعذر إنشاء القيد"); } };
  return <><SectionHeader eyebrow="GENERAL LEDGER / JOURNALS" title="مركز القيود اليومية" description="إنشاء القيد، التحقق من توازنه، ثم اعتماده وترحيله مع سجل تدقيق كامل." action={<Status tone={balanced ? "success" : "warning"}>{balanced ? "القيد متوازن" : "القيد غير مكتمل"}</Status>} /><div className="journal-layout"><article className="suite-card journal-editor"><div className="journal-meta"><label>رقم القيد<input value={journalNo} onChange={(event) => setJournalNo(event.target.value)} /></label><label>تاريخ القيد<input type="date" defaultValue={new Date().toISOString().slice(0, 10)} /></label><label>البيان<input placeholder="وصف العملية المالية" value={description} onChange={(event) => setDescription(event.target.value)} /></label></div><div className="suite-table-head journal-head"><span>الحساب</span><span>البيان</span><span>مدين</span><span>دائن</span><span /></div>{lines.map((line, index) => <div className="journal-line" key={index}><select value={line.accountCode} onChange={(event) => updateLine(index, "accountCode", event.target.value)}><option value="">اختر الحساب</option>{(accounts.data ?? []).map((account: any) => <option key={account.code} value={account.code}>{account.code} · {account.name}</option>)}</select><input placeholder="شرح السطر" value={line.description} onChange={(event) => updateLine(index, "description", event.target.value)} /><input inputMode="decimal" placeholder="0.00" value={line.debit} onChange={(event) => updateLine(index, "debit", event.target.value)} /><input inputMode="decimal" placeholder="0.00" value={line.credit} onChange={(event) => updateLine(index, "credit", event.target.value)} /><button className="suite-icon-button" onClick={() => setLines((current) => current.filter((_, row) => row !== index))}><X size={15} /></button></div>)}<button className="suite-add-line" onClick={addLine}><Plus size={14} />إضافة سطر</button><div className="journal-footer"><div><span>إجمالي المدين</span><b>{money(debits)} ر.ي</b></div><div><span>إجمالي الدائن</span><b>{money(credits)} ر.ي</b></div><button className="suite-primary" disabled={create.isPending} onClick={() => void saveDraft()}><Check size={15} />حفظ والتحقق</button></div></article><aside className="suite-card journal-guide"><p className="suite-eyebrow">POSTING FLOW</p><h3>دورة القيد</h3><div className="flow-step active"><i>01</i><span><b>مسودة</b><small>يمكن التعديل قبل التحقق</small></span></div><div className="flow-step"><i>02</i><span><b>متحقق</b><small>المدين يساوي الدائن</small></span></div><div className="flow-step"><i>03</i><span><b>معتمد</b><small>مراجع مستقل يوافق</small></span></div><div className="flow-step"><i>04</i><span><b>مرحل</b><small>يؤثر في الأستاذ والتقارير</small></span></div><div className={`balance-box ${balanced ? "ok" : "bad"}`}><span>حالة التوازن</span><strong>{money(debits - credits)} ر.ي</strong><small>{balanced ? "القيد جاهز للحفظ" : "أدخل مبالغ متساوية"}</small></div></aside></div></>;
}

function InventoryCatalogView() {
  const master = trpc.masterData.useQuery();
  const save = trpc.windows.saveItem.useMutation();
  const remove = trpc.windows.deleteItem.useMutation();
  const [search, setSearch] = useState("");
  const [selected, setSelected] = useState<any | null>(null);
  const [form, setForm] = useState({ code: "", description: "", unitCost: "0", revenueAccount: "4100", inventoryAccount: "1300", cogsAccount: "5100", stockFlag: 1 });
  const items = (master.data?.items ?? []).filter((item: any) => `${item.code} ${item.description}`.toLowerCase().includes(search.toLowerCase()));
  const edit = (item?: any) => { setSelected(item || null); setForm({ code: item?.code || "", description: item?.description || "", unitCost: String(item?.unitCost || "0"), revenueAccount: item?.revenueAccount || "4100", inventoryAccount: item?.inventoryAccount || "1300", cogsAccount: item?.cogsAccount || "5100", stockFlag: Number(item?.stockFlag ?? 1) }); };
  const update = (key: string, value: string | number) => setForm((current) => ({ ...current, [key]: value }));
  const saveItem = async () => { if (!form.code.trim() || !form.description.trim()) return toast.error("كود الصنف والوصف مطلوبان"); try { await save.mutateAsync({ id: selected?.id, companyId: 1, ...form }); toast.success(selected ? "تم تعديل الصنف" : "تمت إضافة الصنف"); edit(); await master.refetch(); } catch (error) { toast.error(error instanceof Error ? error.message : "تعذر حفظ الصنف"); } };
  const deleteItem = async () => { if (!selected?.id || !window.confirm("سيتم إيقاف الصنف المرتبط بدل حذفه. هل تريد المتابعة؟")) return; try { await remove.mutateAsync({ id: Number(selected.id), actor: "accounting.user" }); toast.success("تم حذف/إيقاف الصنف"); edit(); await master.refetch(); } catch (error) { toast.error(error instanceof Error ? error.message : "تعذر حذف الصنف"); } };
  return <><SectionHeader eyebrow="INVENTORY / MASTER DATA" title="الأصناف والمستودعات" description="بحث سريع من قاعدة البيانات، وإدارة أصناف مرتبطة بحسابات المبيعات والمخزون والتكلفة." action={<button className="suite-primary" onClick={() => edit()}><Plus size={15} />صنف جديد</button>} /><div className="suite-toolbar"><div className="suite-search"><Search size={16} /><input placeholder="ابحث بكود الصنف أو الوصف..." value={search} onChange={(event) => setSearch(event.target.value)} /></div><Status tone="success">{master.isFetching ? "جارٍ التحديث" : `${number(items.length)} صنف`}</Status></div><div className="inventory-layout"><article className="suite-card inventory-list"><div className="suite-table-head inventory-head"><span>الصنف</span><span>التكلفة</span><span>حساب المخزون</span><span>الحالة</span></div>{items.map((item: any) => <button className={`inventory-row ${selected?.id === item.id ? "selected" : ""}`} key={item.id} onClick={() => edit(item)}><div><b>{item.code}</b><span>{item.description}</span></div><span>{money(item.unitCost)} ر.ي</span><span>{item.inventoryAccount || "1300"}</span><Status tone={item.active === 0 ? "warning" : "success"}>{item.active === 0 ? "موقوف" : "نشط"}</Status></button>)}{!items.length && <EmptyState title="لا توجد أصناف مطابقة" detail="أضف صنفًا جديدًا أو غيّر عبارة البحث." icon={Package} />}</article><aside className="suite-card item-editor"><div className="suite-card-head"><div><p className="suite-eyebrow">ITEM PROFILE</p><h3>{selected ? "تعديل الصنف" : "صنف جديد"}</h3></div>{selected && <button className="suite-icon-button" onClick={() => edit()}><X size={14} /></button>}</div><div className="settings-form"><label>كود الصنف<input value={form.code} onChange={(event) => update("code", event.target.value.toUpperCase())} /></label><label>الوصف<input value={form.description} onChange={(event) => update("description", event.target.value)} /></label><label>التكلفة الافتتاحية<input inputMode="decimal" value={form.unitCost} onChange={(event) => update("unitCost", event.target.value)} /></label><div className="item-account-fields"><label>حساب المبيعات<input value={form.revenueAccount} onChange={(event) => update("revenueAccount", event.target.value)} /></label><label>حساب المخزون<input value={form.inventoryAccount} onChange={(event) => update("inventoryAccount", event.target.value)} /></label><label>حساب التكلفة<input value={form.cogsAccount} onChange={(event) => update("cogsAccount", event.target.value)} /></label></div><label className="item-checkbox"><input type="checkbox" checked={form.stockFlag === 1} onChange={(event) => update("stockFlag", event.target.checked ? 1 : 0)} /> صنف مخزني</label><button className="suite-primary" onClick={() => void saveItem()} disabled={save.isPending}><Check size={15} />{selected ? "حفظ التعديل" : "إضافة الصنف"}</button>{selected && <button className="suite-danger-button" onClick={() => void deleteItem()}><X size={14} />حذف / إيقاف</button>}</div></aside></div></>;
}

function InvoiceCycleView({ kind }: { kind: "sales" | "purchases" }) {
  const master = trpc.masterData.useQuery();
  const createSale = trpc.invoices.create.useMutation();
  const postSale = trpc.invoices.post.useMutation();
  const createPurchase = trpc.purchases.create.useMutation();
  const postPurchase = trpc.purchases.post.useMutation();
  const [search, setSearch] = useState("");
  const [docNo, setDocNo] = useState(`${kind === "sales" ? "SI" : "PI"}-${new Date().getFullYear()}-0001`);
  const [partyId, setPartyId] = useState("");
  const [warehouseId, setWarehouseId] = useState("");
  const [itemId, setItemId] = useState("");
  const [quantity, setQuantity] = useState("1");
  const [unitPrice, setUnitPrice] = useState("0");
  const [taxAmount, setTaxAmount] = useState("0");
  const data = master.data ?? { customers: [], suppliers: [], items: [], warehouses: [] };
  const parties = kind === "sales" ? data.customers : data.suppliers;
  const items = data.items.filter((item: any) => `${item.code} ${item.description}`.toLowerCase().includes(search.toLowerCase())).slice(0, 20);
  const total = Number(quantity || 0) * Number(unitPrice || 0) + Number(taxAmount || 0);
  const submit = async () => { if (!partyId || !warehouseId || !itemId) return toast.error("اختر الطرف والمستودع والصنف أولًا"); const lines = [{ itemId: Number(itemId), quantity, unitPrice, taxAmount, unitCode: "EA" }]; try { const created = kind === "sales" ? await createSale.mutateAsync({ docNo, customerId: Number(partyId), warehouseId: Number(warehouseId), currencyCode: "YER", exchangeRate: "1", paymentMethod: "CREDIT", paidAmount: "0", lines, actor: "accounting.user" }) : await createPurchase.mutateAsync({ docNo, supplierId: Number(partyId), warehouseId: Number(warehouseId), currencyCode: "YER", exchangeRate: "1", paymentMethod: "CREDIT", paidAmount: "0", lines, actor: "accounting.user" }); const invoiceId = Number((created as any).invoiceId || (created as any).id); if (kind === "sales") await postSale.mutateAsync({ invoiceId, actor: "accounting.user" }); else await postPurchase.mutateAsync({ invoiceId, actor: "accounting.user" }); toast.success(`تم إنشاء وترحيل ${docNo} مع أثر الأستاذ والمخزون`); } catch (error) { toast.error(error instanceof Error ? error.message : "تعذر ترحيل الفاتورة"); } };
  const title = kind === "sales" ? "فاتورة مبيعات جديدة" : "فاتورة مشتريات جديدة";
  return <><SectionHeader eyebrow={kind === "sales" ? "AR / SALES" : "AP / PURCHASES"} title={kind === "sales" ? "المبيعات والذمم المدينة" : "المشتريات والدائنون"} description="إدخال حقيقي من البيانات الرئيسية ثم ترحيل ذري إلى الأستاذ والذمم والمخزون." action={<Status tone="success">YER · ريال يمني</Status>} /><div className="invoice-layout"><article className="suite-card invoice-form"><div className="suite-card-head"><div><p className="suite-eyebrow">TRANSACTION WINDOW</p><h3>{title}</h3></div><Status>مسودة قبل الحفظ</Status></div><div className="invoice-fields"><label>رقم المستند<input value={docNo} onChange={(event) => setDocNo(event.target.value)} /></label><label>{kind === "sales" ? "العميل" : "المورد"}<select value={partyId} onChange={(event) => setPartyId(event.target.value)}><option value="">اختر {kind === "sales" ? "العميل" : "المورد"}</option>{parties.map((party: any) => <option key={party.id} value={party.id}>{party.code} · {party.legalName}</option>)}</select></label><label>المستودع<select value={warehouseId} onChange={(event) => setWarehouseId(event.target.value)}><option value="">اختر المستودع</option>{data.warehouses.map((warehouse: any) => <option key={warehouse.id} value={warehouse.id}>{warehouse.code} · {warehouse.name}</option>)}</select></label></div><div className="invoice-line-heading"><h4>تفاصيل المستند</h4><span>يُستجلب الصنف من قاعدة البيانات</span></div><div className="item-picker"><div className="suite-search"><Search size={15} /><input placeholder="ابحث عن الصنف بالكود أو الاسم..." value={search} onChange={(event) => setSearch(event.target.value)} /></div>{items.slice(0, 6).map((item: any) => <button className={itemId === String(item.id) ? "picked" : ""} key={item.id} onClick={() => { setItemId(String(item.id)); setUnitPrice(String(item.unitCost || "0")); }}><b>{item.code}</b><span>{item.description}</span><small>{money(item.unitCost)} ر.ي</small></button>)}{!items.length && <span className="picker-empty">لا توجد أصناف مطابقة</span>}</div><div className="invoice-line-inputs"><label>الكمية<input inputMode="decimal" value={quantity} onChange={(event) => setQuantity(event.target.value)} /></label><label>السعر<input inputMode="decimal" value={unitPrice} onChange={(event) => setUnitPrice(event.target.value)} /></label><label>الضريبة<input inputMode="decimal" value={taxAmount} onChange={(event) => setTaxAmount(event.target.value)} /></label><div><span>الإجمالي</span><b>{money(total)} ر.ي</b></div></div><div className="invoice-footer"><span>سيتم إنشاء القيد وتحديث الرصيد داخل معاملة واحدة.</span><button className="suite-primary" onClick={() => void submit()}><Check size={15} />حفظ وترحيل</button></div></article><aside className="suite-card invoice-summary"><p className="suite-eyebrow">POSTING PREVIEW</p><h3>معاينة الأثر</h3><div className="summary-row"><span>{kind === "sales" ? "حساب العميل" : "حساب المورد"}</span><b>{partyId ? "مرتبط" : "غير محدد"}</b></div><div className="summary-row"><span>المخزون</span><b>{itemId ? "سيُحدّث" : "بانتظار الصنف"}</b></div><div className="summary-row"><span>الأستاذ العام</span><b>قيد مزدوج</b></div><div className="summary-total"><span>إجمالي المستند</span><strong>{money(total)}<small> ر.ي</small></strong></div><div className="posting-contract"><ShieldCheck size={17} /><span>لا يمكن تعديل المستند بعد الترحيل. استخدم العكس أو المرتجع.</span></div></aside></div></>;
}

function MoneyVoucherView({ kind }: { kind: "receipt" | "payment" }) {
  const master = trpc.masterData.useQuery();
  const catalog = trpc.windows.accountCatalog.useQuery({ limit: 500 });
  const createReceipt = trpc.vouchers.receiptCreate.useMutation();
  const postReceipt = trpc.vouchers.receiptPost.useMutation();
  const createPayment = trpc.vouchers.paymentCreate.useMutation();
  const postPayment = trpc.vouchers.paymentPost.useMutation();
  const [voucherNo, setVoucherNo] = useState(`${kind === "receipt" ? "RV" : "PV"}-${new Date().getFullYear()}-${String(Date.now()).slice(-5)}`);
  const [partyId, setPartyId] = useState(""); const [cashAccountCode, setCashAccountCode] = useState(""); const [invoiceId, setInvoiceId] = useState(""); const [amount, setAmount] = useState(""); const [reference, setReference] = useState("");
  const parties = kind === "receipt" ? (master.data?.customers || []) as any[] : (master.data?.suppliers || []) as any[];
  const party = parties.find((row) => String(row.id) === partyId);
  const invoices = trpc.adjustments.searchInvoices.useQuery({ invoiceType: kind === "receipt" ? "SALE" : "PURCHASE", partyId: partyId ? Number(partyId) : undefined, limit: 30 }, { enabled: Boolean(partyId) });
  const accounts = (catalog.data || []) as any[];
  const cashAccounts = accounts.filter((account) => account.active !== 0 && account.allowPosting !== 0 && ["1100", "1110"].some((root) => account.code === root || account.parentCode === root));
  const linkedCash = [...((master.data?.cashBoxes || []) as any[]).map((row) => ({ ...row, kind: "صندوق" })), ...((master.data?.banks || []) as any[]).map((row) => ({ ...row, kind: "بنك" }))];
  const title = kind === "receipt" ? "سند قبض" : "سند صرف";
  const submit = async () => { if (!partyId || !cashAccountCode || !invoiceId || !Number(amount) || Number(amount) <= 0) return toast.error("أكمل الطرف والحساب والفاتورة والمبلغ"); try { if (kind === "receipt") { const created = await createReceipt.mutateAsync({ voucherNo, customerId: Number(partyId), cashAccountCode, currencyCode: "YER", amount, reference: reference || undefined, actor: "accounting.user", allocations: [{ invoiceId: Number(invoiceId), amount }] }); await postReceipt.mutateAsync({ voucherId: Number((created as any).id), actor: "accounting.user" }); } else { const created = await createPayment.mutateAsync({ voucherNo, supplierId: Number(partyId), cashAccountCode, currencyCode: "YER", amount, reference: reference || undefined, actor: "accounting.user", allocations: [{ invoiceId: Number(invoiceId), amount }] }); await postPayment.mutateAsync({ voucherId: Number((created as any).id), actor: "accounting.user" }); } toast.success(`تم ترحيل ${title} وإنشاء القيد تلقائيًا`); setAmount(""); setInvoiceId(""); } catch (error) { toast.error(error instanceof Error ? error.message : `تعذر ترحيل ${title}`); } };
  return <><SectionHeader eyebrow={kind === "receipt" ? "AR / CASH RECEIPTS" : "AP / CASH PAYMENTS"} title={kind === "receipt" ? "سندات القبض والتحصيل" : "سندات الصرف والمدفوعات"} description="السند مرتبط بالطرف والفاتورة والحساب النقدي، وبعد الترحيل يُنشأ قيد يومية وتُحدّث الذمة تلقائيًا." action={<Status tone="success">قيد تلقائي</Status>} /><div className="voucher-layout"><article className="suite-card voucher-editor"><div className="suite-card-head"><div><p className="suite-eyebrow">{kind === "receipt" ? "RECEIPT VOUCHER" : "PAYMENT VOUCHER"}</p><h3>{title} جديد</h3></div><Status>مسودة ← مرحّل</Status></div><div className="voucher-fields"><label>رقم السند<input value={voucherNo} onChange={(event) => setVoucherNo(event.target.value)} /></label><label>{kind === "receipt" ? "العميل" : "المورد"}<select value={partyId} onChange={(event) => { setPartyId(event.target.value); setInvoiceId(""); }}><option value="">اختر الطرف</option>{parties.map((row) => <option key={row.id} value={row.id}>{row.code} · {row.legalName}</option>)}</select></label><label>الصندوق / البنك<select value={cashAccountCode} onChange={(event) => setCashAccountCode(event.target.value)}><option value="">اختر الحساب النقدي</option>{cashAccounts.map((account: any) => <option key={account.code} value={account.code}>{account.code} · {account.name}</option>)}</select></label><label>الفاتورة المرتبطة<select value={invoiceId} onChange={(event) => setInvoiceId(event.target.value)} disabled={!partyId}><option value="">{partyId ? "اختر فاتورة مرحّلة" : "اختر الطرف أولًا"}</option>{(invoices.data || []).map((invoice: any) => <option key={invoice.id || invoice.invoiceId} value={invoice.id || invoice.invoiceId}>{invoice.docNo} · المتبقي {money(invoice.remainingAmount ?? invoice.grandTotal)} ر.ي</option>)}</select></label><label>المبلغ<input inputMode="decimal" value={amount} onChange={(event) => setAmount(event.target.value.replace(/[^0-9.]/g, ""))} placeholder="0.00" /></label><label>المرجع / البيان<input value={reference} onChange={(event) => setReference(event.target.value)} placeholder="رقم التحويل أو الشيك" /></label></div><div className="voucher-accounting-note"><ShieldCheck size={17} /><div><b>القيد الذي سينشأ تلقائيًا</b><span>{kind === "receipt" ? "مدين: الصندوق/البنك · دائن: حساب العميل" : "مدين: حساب المورد · دائن: الصندوق/البنك"}</span></div></div><div className="voucher-footer"><span>{party ? `سيتم تخصيص المبلغ على ${party.legalName}` : "اختر الطرف لمعرفة فواتيره المفتوحة"}</span><button className="suite-primary" disabled={createReceipt.isPending || createPayment.isPending || postReceipt.isPending || postPayment.isPending} onClick={() => void submit()}><Check size={15} />تحقق وترحيل</button></div></article><aside className="suite-card voucher-side"><p className="suite-eyebrow">LINKED CASH ACCOUNTS</p><h3>الحسابات النقدية</h3>{linkedCash.slice(0, 8).map((row: any) => <div className="cash-account-row" key={`${row.kind}-${row.id}`}><div className="cash-account-icon">{row.kind === "صندوق" ? "ص" : "ب"}</div><div><b>{row.name}</b><span>{row.code} · {row.kind}</span></div><Status tone={row.status === "ACTIVE" ? "success" : "warning"}>{row.status === "ACTIVE" ? "نشط" : "موقوف"}</Status></div>)}{!linkedCash.length && <EmptyState title="لا توجد صناديق أو بنوك" detail="أنشئ حسابًا نقديًا من تبويب الصناديق والبنوك." icon={WalletCards} />}</aside></div></>;
}

function CashBankView() {
  const master = trpc.masterData.useQuery(); const saveCash = trpc.windows.saveCashBox.useMutation(); const saveBank = trpc.windows.saveBank.useMutation();
  const [kind, setKind] = useState<"cash" | "bank">("cash"); const [selected, setSelected] = useState<any | null>(null); const [code, setCode] = useState(""); const [name, setName] = useState(""); const [accountNumber, setAccountNumber] = useState(""); const [status, setStatus] = useState<"ACTIVE" | "BLOCKED">("ACTIVE");
  const rows = kind === "cash" ? (master.data?.cashBoxes || []) as any[] : (master.data?.banks || []) as any[];
  const select = (row?: any) => { setSelected(row || null); setCode(row?.code || ""); setName(row?.name || ""); setAccountNumber(row?.accountNumber || ""); setStatus(row?.status || "ACTIVE"); };
  const save = async () => { if (!code.trim() || !name.trim()) return toast.error("الكود والاسم مطلوبان"); try { if (kind === "cash") await saveCash.mutateAsync({ id: selected?.id, companyId: 1, code, name, currencyCode: "YER", status }); else await saveBank.mutateAsync({ id: selected?.id, companyId: 1, code, name, accountNumber: accountNumber || undefined, currencyCode: "YER", status }); toast.success(selected ? "تم تعديل الحساب النقدي وربطه بالدليل" : "تم إنشاء الحساب النقدي وربطه بالدليل"); select(); await master.refetch(); } catch (error) { toast.error(error instanceof Error ? error.message : "تعذر حفظ الحساب النقدي"); } };
  return <><SectionHeader eyebrow="TREASURY / CASH & BANKS" title="إدارة الصناديق والبنوك" description="إنشاء حسابات نقدية مرتبطة تلقائيًا بالدليل، لتظهر مباشرة في سندات القبض والصرف والقيود." action={<button className="suite-primary" onClick={() => select()}><Plus size={15} />حساب نقدي جديد</button>} /><div className="treasury-tabs"><button className={kind === "cash" ? "active" : ""} onClick={() => { setKind("cash"); select(); }}><WalletCards size={16} />الصناديق ({(master.data?.cashBoxes || []).length})</button><button className={kind === "bank" ? "active" : ""} onClick={() => { setKind("bank"); select(); }}><Landmark size={16} />البنوك ({(master.data?.banks || []).length})</button></div><div className="treasury-layout"><article className="suite-card treasury-list">{rows.map((row: any) => <button className={selected?.id === row.id ? "selected" : ""} key={row.id} onClick={() => select(row)}><div className="cash-account-icon">{kind === "cash" ? "ص" : "ب"}</div><div><b>{row.name}</b><span>{row.code}{row.accountNumber ? ` · ${row.accountNumber}` : ""}</span></div><Status tone={row.status === "ACTIVE" ? "success" : "warning"}>{row.status === "ACTIVE" ? "نشط" : "موقوف"}</Status></button>)}{!rows.length && <EmptyState title="لا توجد سجلات" detail="أنشئ أول حساب نقدي من النموذج." icon={WalletCards} />}</article><aside className="suite-card treasury-editor"><div className="suite-card-head"><div><p className="suite-eyebrow">{kind === "cash" ? "CASH BOX" : "BANK ACCOUNT"}</p><h3>{selected ? "تعديل الحساب" : "إنشاء حساب"}</h3></div>{selected && <button className="suite-icon-button" onClick={() => select()}><X size={14} /></button>}</div><div className="settings-form"><label>الكود<input value={code} onChange={(event) => setCode(event.target.value.toUpperCase())} placeholder={kind === "cash" ? "CASH-MAIN" : "BANK-001"} /></label><label>الاسم<input value={name} onChange={(event) => setName(event.target.value)} placeholder={kind === "cash" ? "الصندوق الرئيسي" : "بنك اليمن"} /></label>{kind === "bank" && <label>رقم الحساب<input value={accountNumber} onChange={(event) => setAccountNumber(event.target.value)} /></label>}<label>الحالة<select value={status} onChange={(event) => setStatus(event.target.value as "ACTIVE" | "BLOCKED")}><option value="ACTIVE">نشط</option><option value="BLOCKED">موقوف</option></select></label><button className="suite-primary" onClick={() => void save()}><Check size={15} />{selected ? "حفظ التعديل" : "إنشاء وربط"}</button></div><div className="treasury-note"><ShieldCheck size={15} /><span>عند الإنشاء ينشئ النظام حسابًا فرعيًا تحت 1100 للصندوق أو 1110 للبنك، ويستخدمه تلقائيًا في السندات.</span></div></aside></div></>;
}

